import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Sidebar from '../components/layout/Sidebar';
import Editor from '@monaco-editor/react';
import api from '../services/api';

const LANGUAGES = [
  {
    id: 'java', label: '☕ Java',
    template: `import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Write your code here
        
    }
}`
  },
  {
    id: 'python', label: '🐍 Python',
    template: `# Write your code here
import sys
input = sys.stdin.readline

# Your solution below

`
  },
  {
    id: 'cpp', label: '⚡ C++',
    template: `#include <iostream>
using namespace std;

int main() {
    // Write your code here
    
    return 0;
}`
  },
  {
    id: 'javascript', label: '🌐 JavaScript',
    template: `const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin });

rl.on('line', (line) => {
    // Write your code here
    
});`
  }
];

const DIFFICULTY_COLORS = {
  Easy: { bg: '#e6fff9', color: '#00b894' },
  Medium: { bg: '#fff3e0', color: '#f77f00' },
  Hard: { bg: '#ffe6e6', color: '#ff4444' }
};

export default function CodingModule() {
  const navigate = useNavigate();
  const [questions, setQuestions] = useState([]);
  const [selected, setSelected] = useState(null);
  const [language, setLanguage] = useState(LANGUAGES[0]);
  const [code, setCode] = useState(LANGUAGES[0].template);
  const [output, setOutput] = useState('');
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [filter, setFilter] = useState('All');

  useEffect(() => {
    api.get('/coding/questions')
      .then(res => {
        setQuestions(Array.isArray(res.data) ? res.data : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  const handleLanguageChange = (lang) => {
    setLanguage(lang);
    setCode(lang.template);
    setResults(null);
    setOutput('');
  };

  const handleQuestionSelect = (q) => {
    setSelected(q);
    setResults(null);
    setOutput('');
    setCode(language.template);
  };

  const handleSubmit = async () => {
    if (!selected) return;
    if (!output.trim()) {
      alert('Please enter your output!');
      return;
    }
    setSubmitting(true);
    try {
      const res = await api.post(`/coding/submit/${selected.id}`, {
        output: output.trim(),
        language: language.id,
        code: code
      });
      setResults(res.data);
    } catch {
      setResults({ verdict: 'ERROR', message: 'Submission failed!' });
    } finally {
      setSubmitting(false);
    }
  };

  const filtered = filter === 'All'
    ? questions
    : questions.filter(q => q.difficulty === filter);

  return (
    <div className="app-layout">
      <Sidebar />
      <div className="main-content fade-in" style={{ padding: '1.5rem' }}>

        {!selected ? (
          // Question List
          <>
            <div className="page-header">
              <button className="back-btn" onClick={() => navigate('/dashboard')}>← Back</button>
              <div>
                <h1>💻 Coding Challenges</h1>
                <p style={{ color: 'var(--mid)', fontSize: '0.9rem' }}>
                  Practice coding problems — Company specific
                </p>
              </div>
            </div>

            {/* Filter */}
            <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem' }}>
              {['All', 'Easy', 'Medium', 'Hard'].map(f => (
                <button key={f} onClick={() => setFilter(f)}
                  style={{
                    padding: '0.4rem 1rem', borderRadius: '20px',
                    border: '2px solid',
                    borderColor: filter === f ? '#6c63ff' : 'var(--border)',
                    background: filter === f ? '#6c63ff' : 'transparent',
                    color: filter === f ? 'white' : 'var(--text)',
                    cursor: 'pointer', fontWeight: 600, fontSize: '0.85rem'
                  }}>
                  {f}
                </button>
              ))}
            </div>

            {loading ? (
              <div className="loading-wrap"><div className="spinner"></div></div>
            ) : filtered.length === 0 ? (
              <div className="empty-state">
                <div className="e-icon">📭</div>
                <h3>No questions found</h3>
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.8rem' }}>
                {filtered.map((q, i) => (
                  <div key={q.id}
                    onClick={() => handleQuestionSelect(q)}
                    style={{
                      background: 'var(--card)', borderRadius: '10px',
                      padding: '1rem 1.5rem', cursor: 'pointer',
                      boxShadow: 'var(--shadow)',
                      display: 'flex', justifyContent: 'space-between',
                      alignItems: 'center',
                      transition: 'transform 0.2s',
                      border: '1px solid var(--border)'
                    }}
                    onMouseEnter={e => e.currentTarget.style.transform = 'translateX(4px)'}
                    onMouseLeave={e => e.currentTarget.style.transform = 'translateX(0)'}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                      <span style={{
                        background: '#6c63ff20', color: '#6c63ff',
                        borderRadius: '6px', padding: '0.3rem 0.6rem',
                        fontWeight: 700, fontSize: '0.85rem'
                      }}>#{i + 1}</span>
                      <div>
                        <p style={{ fontWeight: 600, fontSize: '1rem' }}>{q.title}</p>
                        <p style={{ color: 'var(--mid)', fontSize: '0.8rem' }}>
                          🏢 {q.company || 'General'} · 📌 {q.topic || 'Coding'}
                        </p>
                      </div>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                      <span style={{
                        background: DIFFICULTY_COLORS[q.difficulty]?.bg || '#f0f0f0',
                        color: DIFFICULTY_COLORS[q.difficulty]?.color || '#666',
                        padding: '0.3rem 0.8rem', borderRadius: '20px',
                        fontSize: '0.8rem', fontWeight: 600
                      }}>
                        {q.difficulty}
                      </span>
                      <span style={{ color: '#6c63ff', fontWeight: 600 }}>Solve →</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </>
        ) : (
          // Coding Editor
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem', height: 'calc(100vh - 3rem)' }}>

            {/* Left — Question */}
            <div style={{ overflowY: 'auto' }}>
              <button className="back-btn" onClick={() => setSelected(null)}
                style={{ marginBottom: '1rem' }}>
                ← Back to Questions
              </button>

              <div style={{
                background: 'var(--card)', borderRadius: '12px',
                padding: '1.5rem', boxShadow: 'var(--shadow)'
              }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1rem' }}>
                  <h2 style={{ fontSize: '1.3rem', fontWeight: 700 }}>{selected.title}</h2>
                  <span style={{
                    background: DIFFICULTY_COLORS[selected.difficulty]?.bg,
                    color: DIFFICULTY_COLORS[selected.difficulty]?.color,
                    padding: '0.2rem 0.7rem', borderRadius: '20px',
                    fontSize: '0.8rem', fontWeight: 600
                  }}>
                    {selected.difficulty}
                  </span>
                </div>

                <p style={{ color: 'var(--mid)', fontSize: '0.85rem', marginBottom: '1rem' }}>
                  🏢 {selected.company} · 📌 {selected.topic}
                </p>

                <div style={{
                  background: 'var(--bg)', borderRadius: '8px',
                  padding: '1rem', marginBottom: '1rem',
                  fontSize: '0.9rem', lineHeight: 1.7
                }}>
                  {selected.description}
                </div>

                {selected.inputFormat && (
                  <div style={{ marginBottom: '0.8rem' }}>
                    <p style={{ fontWeight: 700, fontSize: '0.85rem', marginBottom: '0.3rem' }}>
                      📥 Input Format:
                    </p>
                    <p style={{ fontSize: '0.85rem', color: 'var(--mid)' }}>{selected.inputFormat}</p>
                  </div>
                )}

                {selected.outputFormat && (
                  <div style={{ marginBottom: '0.8rem' }}>
                    <p style={{ fontWeight: 700, fontSize: '0.85rem', marginBottom: '0.3rem' }}>
                      📤 Output Format:
                    </p>
                    <p style={{ fontSize: '0.85rem', color: 'var(--mid)' }}>{selected.outputFormat}</p>
                  </div>
                )}

                {selected.constraintsText && (
                  <div style={{ marginBottom: '1rem' }}>
                    <p style={{ fontWeight: 700, fontSize: '0.85rem', marginBottom: '0.3rem' }}>
                      ⚠️ Constraints:
                    </p>
                    <p style={{ fontSize: '0.85rem', color: 'var(--mid)' }}>{selected.constraintsText}</p>
                  </div>
                )}

                {/* Test Cases */}
                {selected.testCases && selected.testCases.length > 0 && (
                  <div>
                    <p style={{ fontWeight: 700, fontSize: '0.9rem', marginBottom: '0.5rem' }}>
                      🧪 Sample Test Cases:
                    </p>
                    {selected.testCases.map((tc, i) => (
                      <div key={i} style={{
                        background: '#f8f9fa', borderRadius: '8px',
                        padding: '0.8rem', marginBottom: '0.5rem',
                        border: '1px solid var(--border)'
                      }}>
                        <p style={{ fontSize: '0.8rem', fontWeight: 600 }}>
                          Test Case {i + 1}:
                        </p>
                        <p style={{ fontSize: '0.8rem', color: 'var(--mid)' }}>
                          Input: <code>{tc.input}</code>
                        </p>
                        <p style={{ fontSize: '0.8rem', color: '#00b894' }}>
                          Expected: <code>{tc.expectedOutput}</code>
                        </p>
                      </div>
                    ))}
                    <div style={{
                      background: '#1a1a2e20', borderRadius: '8px',
                      padding: '0.8rem', textAlign: 'center',
                      fontSize: '0.8rem', color: 'var(--mid)'
                    }}>
                      🔒 + {3} Hidden test cases
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Right — Editor */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>

              {/* Language Selector */}
              <div style={{
                background: 'var(--card)', borderRadius: '12px',
                padding: '1rem', boxShadow: 'var(--shadow)',
                display: 'flex', gap: '0.5rem', flexWrap: 'wrap'
              }}>
                {LANGUAGES.map(lang => (
                  <button key={lang.id}
                    onClick={() => handleLanguageChange(lang)}
                    style={{
                      padding: '0.4rem 1rem', borderRadius: '6px',
                      border: '2px solid',
                      borderColor: language.id === lang.id ? '#6c63ff' : 'var(--border)',
                      background: language.id === lang.id ? '#6c63ff' : 'transparent',
                      color: language.id === lang.id ? 'white' : 'var(--text)',
                      cursor: 'pointer', fontWeight: 600, fontSize: '0.85rem'
                    }}>
                    {lang.label}
                  </button>
                ))}
              </div>

              {/* Monaco Editor */}
              <div style={{
                borderRadius: '12px', overflow: 'hidden',
                boxShadow: 'var(--shadow)', flex: 1
              }}>
                <Editor
                  height="350px"
                  language={language.id === 'cpp' ? 'cpp' : language.id}
                  value={code}
                  onChange={val => setCode(val)}
                  theme="vs-dark"
                  options={{
                    fontSize: 14,
                    minimap: { enabled: false },
                    scrollBeyondLastLine: false,
                    lineNumbers: 'on',
                    wordWrap: 'on'
                  }}
                />
              </div>

              {/* Output Input */}
              <div style={{
                background: 'var(--card)', borderRadius: '12px',
                padding: '1rem', boxShadow: 'var(--shadow)'
              }}>
                <p style={{ fontWeight: 700, fontSize: '0.9rem', marginBottom: '0.5rem' }}>
                  📤 Your Output:
                </p>
                <p style={{ fontSize: '0.75rem', color: 'var(--mid)', marginBottom: '0.5rem' }}>
                  Run your code locally → Copy output → Paste here
                </p>
                <textarea
                  rows={3}
                  placeholder="Paste your program output here..."
                  value={output}
                  onChange={e => setOutput(e.target.value)}
                  style={{
                    width: '100%', padding: '0.7rem',
                    borderRadius: '8px', border: '1px solid var(--border)',
                    background: 'var(--bg)', color: 'var(--text)',
                    fontSize: '0.9rem', fontFamily: 'monospace',
                    resize: 'vertical'
                  }}
                />
                <button onClick={handleSubmit} disabled={submitting}
                  style={{
                    background: '#00b894', color: 'white', border: 'none',
                    borderRadius: '8px', padding: '0.7rem 2rem',
                    cursor: 'pointer', fontWeight: 700,
                    fontSize: '0.95rem', marginTop: '0.5rem',
                    width: '100%', opacity: submitting ? 0.7 : 1
                  }}>
                  {submitting ? '⏳ Checking...' : '✅ Submit'}
                </button>
              </div>

              {/* Results */}
              {results && (
                <div style={{
                  background: results.verdict === 'ALL_PASSED' ? '#e6fff9' :
                    results.verdict === 'PARTIAL' ? '#fff3e0' : '#ffe6e6',
                  border: `1px solid ${results.verdict === 'ALL_PASSED' ? '#00b894' :
                    results.verdict === 'PARTIAL' ? '#f77f00' : '#ff4444'}`,
                  borderRadius: '12px', padding: '1rem',
                  boxShadow: 'var(--shadow)'
                }}>
                  <p style={{
                    fontWeight: 700, fontSize: '1rem', marginBottom: '0.5rem',
                    color: results.verdict === 'ALL_PASSED' ? '#00b894' :
                      results.verdict === 'PARTIAL' ? '#f77f00' : '#ff4444'
                  }}>
                    {results.message}
                  </p>
                  <p style={{ fontSize: '0.85rem', marginBottom: '0.8rem' }}>
                    Passed: {results.passed}/{results.total} test cases
                  </p>
                  {results.results?.map((r, i) => (
                    <div key={i} style={{
                      background: r.passed ? '#00b89420' : '#ff444420',
                      borderRadius: '6px', padding: '0.5rem 0.8rem',
                      marginBottom: '0.4rem', fontSize: '0.8rem',
                      display: 'flex', justifyContent: 'space-between'
                    }}>
                      <span>Test {r.testCase}: {r.input !== 'Hidden' ? `Input: ${r.input}` : '🔒 Hidden'}</span>
                      <span style={{
                        fontWeight: 700,
                        color: r.passed ? '#00b894' : '#ff4444'
                      }}>
                        {r.passed ? '✅ Passed' : '❌ Failed'}
                      </span>
                    </div>
                  ))}

                  {results.verdict === 'ALL_PASSED' && (
                    <div style={{ textAlign: 'center', marginTop: '1rem' }}>
                      <p style={{ fontSize: '1.5rem' }}>🎉</p>
                      <p style={{ fontWeight: 700, color: '#00b894' }}>
                        Excellent! Move to next question!
                      </p>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
